result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/eolconv.bats", "content": "#!/usr/bin/env bats

SCRIPT="$BATS_TEST_DIRNAME/eolconv.sh"

setup() {
    TMPDIR_TEST="$(mktemp -d)"
    cd "$TMPDIR_TEST"
}

teardown() {
    rm -rf "$TMPDIR_TEST"
}

# --- to-unix ---------------------------------------------------------------

@test "--to-unix strips CR before LF" {
    printf 'a\r\nb\r\nc\r\n' > f.txt
    run "$SCRIPT" --to-unix f.txt
    [ "$status" -eq 0 ]
    run cat f.txt
    [ "${lines[0]}" = "a" ]
    [ "${lines[1]}" = "b" ]
    [ "${lines[2]}" = "c" ]
    # exactly 3 bytes: a, b, c plus two newlines
    [ "$(wc -c < f.txt)" -eq 5 ]
}

@test "--to-unix leaves plain LF file unchanged in content" {
    printf 'x\ny\n' > plain.txt
    run "$SCRIPT" --to-unix plain.txt
    [ "$status" -eq 0 ]
    printf 'x\ny\n' > expected.txt
    cmp -s plain.txt expected.txt
}

# --- to-dos ----------------------------------------------------------------

@test "--to-dos adds CR before LF" {
    printf 'a\nb\n' > f.txt
    run "$SCRIPT" --to-dos f.txt
    [ "$status" -eq 0 ]
    run od -An -c f.txt
    echo "$output" | grep -q 'a  \\r  \\n'
}

@test "--to-dos does not double existing CRLF endings" {
    printf 'a\r\nb\r\n' > crlf.txt
    run "$SCRIPT" --to-dos crlf.txt
    [ "$status" -eq 0 ]
    printf 'a\r\nb\r\n' > expected.txt
    cmp -s crlf.txt expected.txt
}

# --- backups ---------------------------------------------------------------

@test "creates a .bak backup by default with original content" {
    printf 'a\r\nb\r\n' > f.txt
    run "$SCRIPT" --to-unix f.txt
    [ "$status" -eq 0 ]
    [ -f f.txt.bak ]
    printf 'a\r\nb\r\n' > orig.txt
    cmp -s f.txt.bak orig.txt
}

@test "--no-backup creates no backup file" {
    printf 'a\r\nb\r\n' > f.txt
    run "$SCRIPT" --no-backup --to-unix f.txt
    [ "$status" -eq 0 ]
    [ ! -e f.txt.bak ]
}

# --- idempotency -----------------------------------------------------------

@test "--to-unix is idempotent" {
    printf 'a\r\nb\r\n' > f.txt
    "$SCRIPT" --to-unix f.txt
    cp f.txt first.txt
    "$SCRIPT" --to-unix f.txt
    cmp -s first.txt f.txt
}

@test "--to-dos is idempotent" {
    printf 'a\nb\n' > f.txt
    "$SCRIPT" --to-dos f.txt
    cp f.txt first.txt
    "$SCRIPT" --to-dos f.txt
    cmp -s first.txt f.txt
}

# --- binary skip and exit code ---------------------------------------------

@test "skips file containing NUL byte, reports on stderr, exits 3" {
    printf 'text\x00binary\r\ndata\n' > bin.dat
    printf 'ok\r\n' > good.txt
    run "$SCRIPT" --to-unix bin.dat good.txt
    [ "$status" -eq 3 ]
    [[ "$output" == *"bin.dat"* ]]
    # binary file untouched
    printf 'text\x00binary\r\ndata\n' > orig.dat
    cmp -s bin.dat orig.dat
    # no backup for the skipped file, but other file converted
    [ ! -e bin.dat.bak ]
    grep -q $'\r' <(head -c 20 good.txt)
}
"})
print(result)
